            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "It is reasonable to assume that, by and large, what is not read now will not be read, ever. It is also reasonable to assume that practically nothing that is read now will be read later. Finally, it is not too farfetched to imagine a future in which novels are not read at all.", Author = "Gore Vidal" },
