            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Think of the earth as a living organism that is being attacked by billions of bacteria whose numbers double every forty years. Either the host dies, or the virus dies, or both die.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "The corporate grip on opinion in the United States is one of the wonders of the Western World. No First World country has ever managed to eliminate so entirely from its media all objectivity — much less dissent.", Author = "Gore Vidal" },
