            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Lonely children often have imaginary playmates but I was never lonely; rather, I was solitary, and wanted no company at all other than books and movies, and my own imagination.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Apparently, a concern for others is self-love at its least attractive, while greed is now a sign of the higher altruism. But then to reverse, periodically, the meanings of words is a very small price to pay for the freedom not only to conform but to consume.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "By and large, serious fiction was the work of victims who portrayed victims for an audience of victims who, it was oddly assumed, would want to see their lives realistically portrayed.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "As societies grow decadent, the language grows decadent, too. Words are used to disguise, not to illuminate, action: you liberate a city by destroying it. Words are to confuse, so that at election time people will solemnly vote against their own interests.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "American society, literary or lay, tends to be humorless. What other culture could have produced someone like Hemingway and not seen the joke?", Author = "Gore Vidal" },
