            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Apparently, \"conspiracy stuff\" is now shorthand for unspeakable truth.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Post-9/11, the American media were filled with pre-emptory denunciations of unpatriotic 'conspiracy theorists', who not only are always with us but are usually easy for the media to discredit since it is an article of faith that there are no conspiracies in American life.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Happily for the busy lunatics who rule over us, we are permanently the United States of Amnesia. We learn nothing because we remember nothing.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "We have ceased to be a nation under law but instead a homeland where the withered Bill of Rights, like a dead trumpet vine, clings to our pseudo-Roman columns.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Lennon was somebody who was a born enemy of those who govern the United States. He was everything they hated. So I just say that he represented life, and is admirable; and Mr. Nixon and Mr. Bush represent death, and that is a bad thing.", Author = "Gore Vidal" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Gore_Vidal", Text = "Private lives should be no business of the State. The State is bad enough as it is. It cannot educate or medicate or feed the people; it cannot do anything but kill the people. No State like that do we want prying into our private lives.", Author = "Gore Vidal" },
